import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

// Flyweight: only intrinsic (shared) state. Immutable by construction.
final class TreeType {
    private final String species;
    private final String texture;
    private final String mesh;

    TreeType(String species, String texture, String mesh) {
        this.species = species;
        this.texture = texture;
        this.mesh = mesh;
    }

    // Extrinsic state (x, y, height) is passed in, never stored.
    void draw(Canvas canvas, int x, int y, int height) {
        canvas.drawMesh(mesh, texture, x, y, height);
    }

    String key() { return species + "|" + texture + "|" + mesh; }
}

// Factory: the single place where sharing is enforced.
final class TreeFactory {
    private final Map<String, TreeType> pool = new ConcurrentHashMap<>();

    TreeType get(String species, String texture, String mesh) {
        String key = species + "|" + texture + "|" + mesh;
        // Trade-off: lookup cost per creation in exchange for O(1) types.
        return pool.computeIfAbsent(key, k -> new TreeType(species, texture, mesh));
    }

    int variantCount() { return pool.size(); }
}

// Context: tiny object holding extrinsic state + a reference.
final class Tree {
    private final int x, y, height;
    private final TreeType type;

    Tree(int x, int y, int height, TreeType type) {
        this.x = x; this.y = y; this.height = height; this.type = type;
    }

    void draw(Canvas canvas) {
        type.draw(canvas, x, y, height);
    }
}

interface Canvas {
    void drawMesh(String mesh, String texture, int x, int y, int height);
}
